"""Demo: discrete Brouwer fixed points for random self-maps.

For random self-maps g of {0,...,n}, extracts the combinatorial fixed point
guaranteed by the discrete Brouwer theorem via the sign change of the
displacement j - g(j), and verifies the fixed-point inequalities.
"""
from __future__ import annotations
import random
from typing import List, Optional


def discrete_ivt(values: List[int]) -> Optional[int]:
    for i in range(len(values) - 1):
        if values[i] <= 0 <= values[i + 1]:
            return i
    return None


def discrete_brouwer(g: List[int]) -> Optional[int]:
    return discrete_ivt([j - g[j] for j in range(len(g))])


def main() -> None:
    random.seed(1)
    n = 25
    successes = 0
    trials = 50000
    for _ in range(trials):
        g = [random.randint(0, n) for _ in range(n + 1)]
        i = discrete_brouwer(g)
        if i is not None and i <= g[i] and g[i + 1] <= i + 1:
            successes += 1
    print(f"{successes}/{trials} random self-maps of {{0,...,{n}}} yielded a valid")
    print("approximate fixed point i with i <= g(i) and g(i+1) <= i+1.")


if __name__ == "__main__":
    main()

"""Demo: best-response dynamics and the pure-deviation principle.

Builds the best-response payoff table for a 2x2 game and shows that the
pure-deviation principle (checking only pure deviations) agrees with an exhaustive
mixed-strategy grid search for detecting Nash equilibria.
"""
from __future__ import annotations
from fractions import Fraction
from typing import List, Sequence


def E(u: List[List[Fraction]], p: Sequence[Fraction], q: Sequence[Fraction]) -> Fraction:
    return sum(p[i] * q[j] * u[i][j] for i in range(len(u)) for j in range(len(u[0])))


def pure(k: int, size: int) -> List[Fraction]:
    return [Fraction(1) if i == k else Fraction(0) for i in range(size)]


def is_nash_pure(u1, u2, p, q) -> bool:
    b1, b2 = E(u1, p, q), E(u2, p, q)
    if any(E(u1, pure(a, len(u1)), q) > b1 for a in range(len(u1))):
        return False
    if any(E(u2, p, pure(b, len(u1[0]))) > b2 for b in range(len(u1[0]))):
        return False
    return True


def is_nash_grid(u1, u2, p, q, steps: int = 20) -> bool:
    b1, b2 = E(u1, p, q), E(u2, p, q)
    for k in range(steps + 1):
        pk = [Fraction(k, steps), Fraction(steps - k, steps)]
        if E(u1, pk, q) > b1 + Fraction(1, 10 ** 6):
            return False
        if E(u2, p, pk) > b2 + Fraction(1, 10 ** 6):
            return False
    return True


def main() -> None:
    # Prisoner's Dilemma
    u1 = [[Fraction(3), Fraction(0)], [Fraction(5), Fraction(1)]]
    u2 = [[Fraction(3), Fraction(5)], [Fraction(0), Fraction(1)]]
    defect = pure(1, 2)
    print("Prisoner's Dilemma, mutual defection:")
    print(f"  pure-deviation principle says Nash: {is_nash_pure(u1, u2, defect, defect)}")
    print(f"  exhaustive grid search agrees      : {is_nash_grid(u1, u2, defect, defect)}")


if __name__ == "__main__":
    main()

