from fractions import Fraction
from typing import List, Sequence


def is_nash_equilibrium(u1: List[List[Fraction]],
                        u2: List[List[Fraction]],
                        p: Sequence[Fraction],
                        q: Sequence[Fraction]) -> bool:
    """Certify a Nash equilibrium in O(|I|*|J|) via the pure-deviation principle.

    (p, q) is a Nash equilibrium iff both are distributions and no pure deviation
    of either player strictly beats the incumbent payoff.
    """
    rows, cols = len(u1), len(u1[0])

    def E(u: List[List[Fraction]], x: Sequence[Fraction], y: Sequence[Fraction]) -> Fraction:
        return sum(x[i] * y[j] * u[i][j] for i in range(rows) for j in range(cols))

    def is_dist(v: Sequence[Fraction]) -> bool:
        return all(t >= 0 for t in v) and sum(v) == 1

    if not (is_dist(p) and is_dist(q)):
        return False
    base1, base2 = E(u1, p, q), E(u2, p, q)
    for a in range(rows):
        ea = [Fraction(1) if i == a else Fraction(0) for i in range(rows)]
        if E(u1, ea, q) > base1:
            return False
    for b in range(cols):
        eb = [Fraction(1) if j == b else Fraction(0) for j in range(cols)]
        if E(u2, p, eb) > base2:
            return False
    return True
